// App.js - The main component that sets up routing and layout
// React Router lets us have multiple "pages" in our single-page app

import React from 'react';
import { BrowserRouter as Router, Routes, Route, NavLink } from 'react-router-dom';
import Dashboard from './pages/Dashboard';
import AlertsPage from './pages/AlertsPage';
import RawDataPage from './pages/RawDataPage';
import './App.css';

function App() {
  return (
    <Router>
      <div className="app-container">

        {/* ---- SIDEBAR NAVIGATION ---- */}
        <nav className="sidebar">
          <div className="sidebar-header">
            <div className="logo-icon">📡</div>
            <h1 className="sidebar-title">IoT Dashboard</h1>
          </div>

          <ul className="nav-list">
            {/* NavLink automatically adds "active" class to the current page */}
            <li>
              <NavLink to="/" end className={({ isActive }) => isActive ? 'nav-link active' : 'nav-link'}>
                <span className="nav-icon">🏠</span>
                Dashboard
              </NavLink>
            </li>
            <li>
              <NavLink to="/alerts" className={({ isActive }) => isActive ? 'nav-link active' : 'nav-link'}>
                <span className="nav-icon">🚨</span>
                Alerts
              </NavLink>
            </li>
            <li>
              <NavLink to="/raw-data" className={({ isActive }) => isActive ? 'nav-link active' : 'nav-link'}>
                <span className="nav-icon">📊</span>
                Raw Data
              </NavLink>
            </li>
          </ul>

          <div className="sidebar-footer">
            <p>IoT Monitor v1.0</p>
          </div>
        </nav>

        {/* ---- MAIN CONTENT AREA ---- */}
        <main className="main-content">
          {/* Routes define which component renders for each URL */}
          <Routes>
            <Route path="/" element={<Dashboard />} />
            <Route path="/alerts" element={<AlertsPage />} />
            <Route path="/raw-data" element={<RawDataPage />} />
          </Routes>
        </main>

      </div>
    </Router>
  );
}

export default App;
